const response = $json;

let textItem;
try {
  textItem = response.content.find(c => c.type === 'text');
} catch(e) {
  return [{ json: {
    status: "skipped", quality_score: 1, lead_signal_score: 1,
    content_idea_score: 1, competitor_strength: 1,
    entity_type: "irrelevant", recommended_action: "ignore",
    freshness_status: "unknown",
    reason: "No content array in response: " + e.message,
    test_pass_basic: false,
    raw_response_preview: JSON.stringify(response).substring(0, 500)
  }}];
}

if (!textItem) {
  return [{ json: {
    status: "skipped", quality_score: 1, lead_signal_score: 1,
    content_idea_score: 1, competitor_strength: 1,
    entity_type: "irrelevant", recommended_action: "ignore",
    freshness_status: "unknown",
    reason: "No text item found in Claude response content array",
    test_pass_basic: false,
    raw_response_preview: JSON.stringify(response.content).substring(0, 500)
  }}];
}

let parsed;
try {
  let rawText = textItem.text.trim();
  rawText = rawText.replace(/^```json\s*/, '').replace(/\s*```$/, '');
  rawText = rawText.replace(/^```\s*/, '').replace(/\s*```$/, '').trim();
  parsed = JSON.parse(rawText);
} catch(e) {
  return [{ json: {
    status: "skipped", quality_score: 1, lead_signal_score: 1,
    content_idea_score: 1, competitor_strength: 1,
    entity_type: "irrelevant", recommended_action: "ignore",
    freshness_status: "unknown",
    reason: "JSON parse failed: " + e.message,
    test_pass_basic: false,
    raw_response_preview: textItem.text.substring(0, 500)
  }}];
}

// Pull test metadata from Select Test Record node (available in execution context)
let testMeta = {};
try {
  testMeta = $('Select Test Record').first().json;
} catch(e) {
  testMeta = { test_id: 0, expected_entity_type: "", expected_recommended_action: "", expected_quality_range: "" };
}

const actualQuality   = parsed.quality_score      || 1;
const actualEntity    = parsed.entity_type         || "";
const actualAction    = parsed.recommended_action  || "";
const actualLead      = parsed.lead_signal_score   || 1;
const actualContent   = parsed.content_idea_score  || 1;
const actualComp      = parsed.competitor_strength || 1;

const entityMatch  = (actualEntity === testMeta.expected_entity_type);
const testPassBasic = entityMatch && (parsed.status !== undefined);

return [{ json: {
  ...parsed,
  test_id:                      testMeta.test_id || 0,
  expected_entity_type:         testMeta.expected_entity_type || "",
  expected_recommended_action:  testMeta.expected_recommended_action || "",
  expected_quality_range:       testMeta.expected_quality_range || "",
  actual_entity_type:           actualEntity,
  actual_recommended_action:    actualAction,
  actual_quality_score:         actualQuality,
  actual_lead_signal_score:     actualLead,
  actual_content_idea_score:    actualContent,
  actual_competitor_strength:   actualComp,
  test_pass_basic:              testPassBasic,
  test_notes: "entity_type_match=" + entityMatch
    + "; quality=" + actualQuality
    + "; action=" + actualAction
    + "; expected_action=" + (testMeta.expected_recommended_action || "")
}}];
